package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.identity.NodeTokens;import com.lianxibu.site.repository.identity.JdbcNodeStore;import com.lianxibu.site.repository.jobs.*;import com.lianxibu.site.service.identity.*;
import java.time.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;import javax.sql.DataSource;import org.junit.jupiter.api.*;import org.springframework.jdbc.datasource.DataSourceTransactionManager;
class CollectorHostMemoryServiceTest {
 CollectorHostMemoryNativeTest f;CollectorHostMemoryService service;NodeIdentityService identity;JdbcNodeStore nodes;String token;AtomicReference<Instant> at;Clock clock;
 DataSource source(){return new CollectorHostMemoryNativeTest().source();}
 @BeforeEach void setup()throws Exception{f=new CollectorHostMemoryNativeTest(){@Override DataSource source(){return CollectorHostMemoryServiceTest.this.source();}};f.setup();f.f.jdbc.execute("CREATE TABLE IF NOT EXISTS worker_lock(id INT PRIMARY KEY)");if(f.f.jdbc.queryForObject("SELECT COUNT(*) FROM worker_lock WHERE id=1",Integer.class)==0)f.f.jdbc.update("INSERT INTO worker_lock VALUES(1)");at=new AtomicReference<>(f.now);clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return at.get();}};var tokens=new NodeTokens(new byte[32]);token=tokens.issue("fictional-owner","fictional-host-memory","fictional-key",f.f.node);f.f.jdbc.update("UPDATE collector_nodes SET token_hash=? WHERE id=?",NodeTokens.digest(token),f.f.node);nodes=new JdbcNodeStore(f.f.db);identity=new NodeIdentityService(nodes,tokens,clock);service=create(new DataSourceTransactionManager(f.f.db));}
 CollectorHostMemoryService create(org.springframework.transaction.PlatformTransactionManager tx){return new CollectorHostMemoryService(f.store,identity,new SharedWriteExecutor(new JdbcSharedWriteEntry(f.f.db),tx),clock);}
 @AfterEach void cleanup(){if(f!=null)f.cleanup();}
 byte[] raw(Instant observed,long sequence,long rss){return f.body(observed,sequence,rss).canonical().getBytes(java.nio.charset.StandardCharsets.UTF_8);}
 @Test void nativeBearerOriginalSoleWriterAndOldAckReplayNeverRefreshHistoryOrHeartbeat(){var original=service.submit(token,raw(f.now,1,10));at.set(f.now.plusSeconds(600));assertEquals(original,service.submit(token,raw(f.now,1,10)));assertEquals(f.now,original.receivedAt());assertEquals(1,f.f.tx.execute(s->f.store.latest(f.f.node,1)).revision());assertNull(nodes.byTokenHash(NodeTokens.digest(token)).lastSeenAt());assertNull(f.f.tx.execute(s->f.f.store.latest(f.f.node,1)));}
 @Test void currentNativePermissionOrRevocationPreventsEvenRetainedAck(){var body=raw(f.now,1,10);service.submit(token,body);assertEquals(1,nodes.setPermissions(f.f.node,1,"[]","[]"));assertThrows(IdentityService.Rejected.class,()->service.submit(token,body));assertEquals(1,f.f.tx.execute(s->f.store.original(f.f.node)).revision());f.f.jdbc.update("UPDATE collector_nodes SET enabled=0 WHERE id=?",f.f.node);assertThrows(IdentityService.Rejected.class,()->service.submit(token,body));}
 @Test void actualConcurrentSubmissionsKeepOneNativeSettingAndOneOriginalAck()throws Exception{var bytes=raw(f.now,1,10);var pool=Executors.newFixedThreadPool(2);var ready=new CountDownLatch(1);Callable<JdbcCollectorHostMemory.Entry> action=()->{assertTrue(ready.await(5,TimeUnit.SECONDS));return service.submit(token,bytes);};try{var first=pool.submit(action);var second=pool.submit(action);ready.countDown();assertEquals(first.get(10,TimeUnit.SECONDS),second.get(10,TimeUnit.SECONDS));assertEquals(1,f.f.tx.execute(s->f.store.latest(f.f.node,1)).revision());}finally{pool.shutdownNow();}}
 @Test void actualFreshnessBoundaryFutureInvalidOrUnauthorizedBodyCannotStoreReceipt(){assertThrows(IllegalArgumentException.class,()->service.submit(token,raw(f.now.plusNanos(1000),1,10)));assertThrows(IllegalArgumentException.class,()->service.submit(token,raw(f.now.minusSeconds(120).minusNanos(1000),1,10)));assertThrows(RuntimeException.class,()->service.submit(token,"{}".getBytes(java.nio.charset.StandardCharsets.UTF_8)));assertThrows(IdentityService.Rejected.class,()->service.submit("fictional-invalid-token",raw(f.now,1,10)));assertNull(f.f.tx.execute(s->f.store.latest(f.f.node,1)));at.set(f.now.plusSeconds(120));assertEquals(f.now.plusSeconds(120),service.submit(token,raw(f.now,1,10)).receivedAt());assertNull(nodes.byTokenHash(NodeTokens.digest(token)).lastSeenAt());}
 @Test void outerTransactionOrConflictingSequenceCannotOverwriteOriginalCanonicalFacts(){assertThrows(IllegalStateException.class,()->f.f.tx.execute(s->service.submit(token,raw(f.now,1,10))));assertNull(f.f.tx.execute(s->f.store.latest(f.f.node,1)));service.submit(token,raw(f.now,1,10));assertThrows(JdbcCollectorHostMemory.Conflict.class,()->service.submit(token,raw(f.now,1,11)));assertEquals(10,f.f.tx.execute(s->f.store.latest(f.f.node,1)).latest().input().sample().rssBytes());}
 @Test void actualCommitAckLossResolvesOriginalNativeReceiptAndNeverPerformsSecondWrite(){var manager=new AckLoss(f.f.db);service=create(manager);manager.armed=true;var value=service.submit(token,raw(f.now,1,10));assertFalse(manager.armed);assertEquals(f.now,value.receivedAt());service=create(new DataSourceTransactionManager(f.f.db));at.set(f.now.plusSeconds(600));assertEquals(value,service.submit(token,raw(f.now,1,10)));assertEquals(1,f.f.tx.execute(s->f.store.latest(f.f.node,1)).revision());assertNull(nodes.byTokenHash(NodeTokens.digest(token)).lastSeenAt());}
 static final class AckLoss extends DataSourceTransactionManager{boolean armed;AckLoss(DataSource source){super(source);}@Override protected void doCommit(org.springframework.transaction.support.DefaultTransactionStatus status){super.doCommit(status);if(armed&&!status.isReadOnly()){armed=false;throw new org.springframework.transaction.TransactionSystemException("fictional commit acknowledgement lost");}}}
}
